package org.telegram.tgnet;import java.time.*;import java.util.*;public class ConnectionsManager {public static final ConnectionsManager INSTANCE=new ConnectionsManager();public static int calls,returned;public static boolean gap=false,oneSided=false;public static ConnectionsManager getInstance(int a){return INSTANCE;}public int sendRequest(TLObject object,RequestDelegate callback){TLRPC.TL_messages_getHistory q=(TLRPC.TL_messages_getHistory)object;calls++;TLRPC.Response result=new TLRPC.Response();long today=LocalDate.now().toEpochDay();long end=Instant.ofEpochSecond(q.offset_date).atZone(ZoneId.systemDefault()).toLocalDate().toEpochDay();long day=end-1;long back=today-day;if(back<150 && !(gap&&back==2)){int base=(int)((200-back)*200000);int limit=(back==3?130000:2);int start=q.offset_id==0?0:base-q.offset_id+1;for(int j=start;j<Math.min(start+q.limit,limit);j++){boolean outgoing=oneSided||j%2==0;int date=(int)LocalDate.ofEpochDay(day).atStartOfDay(ZoneId.systemDefault()).toEpochSecond()+43200;result.messages.add(new TLRPC.Message(base-j,date,outgoing));}}returned+=result.messages.size();callback.run(result,null);return calls;}public void cancelRequest(int id,boolean yes){}}